"use client";

import * as React from "react";
import { HugeiconsIcon } from "@hugeicons/react";
import { PauseIcon, PlayIcon } from "@hugeicons/core-free-icons";
import { IsoFigure, Line, Solid } from "@/components/anatomy/react/draw";
import { asksForStillness, follow, useInView, useStillness } from "@/components/anatomy/react/live";
import { translateAlong } from "@/components/anatomy/iso-kit";
import {
  BACK_LINES,
  BACK_PARTS,
  BELT_SLATS,
  BELT_TRIM_LINES,
  CARRIERS,
  FRONT_LINES,
  FRONT_PARTS,
  HEIGHT,
  IN_LINES,
  IN_PARTS,
  MESSY_LINES,
  MESSY_PARTS,
  NEAT_LINES,
  NEAT_PARTS,
  NEAR_LINES,
  NEAR_PARTS,
  P,
  PERIOD,
  STILL_PHASE,
  SWAP,
  TRAY_LINES,
  TRAY_PARTS,
  VAULT_LINES,
  VAULT_PARTS,
  WIDTH,
  beamAt,
  beamZ,
  carrierX,
  phaseAt,
  scanGlow,
  stateText,
} from "./scanner";
import "./the-scanner.css";

const MOST_DT = 1 / 30;
const SEEK = 0.12; // seconds for the belt to answer a reader's hand

const clamp01 = (x: number) => (x < 0 ? 0 : x > 1 ? 1 : x);

/**
 * A still frame to check the drawing by: `?pose=0` holds the belt at the top of
 * the run, `?pose=1` at the end, anything between scrubs to there. Dev only.
 */
function posedFromQuery(): number | null {
  if (!import.meta.env.DEV || typeof window === "undefined") return null;
  const raw = new URLSearchParams(window.location.search).get("pose");
  if (raw === null) return null;
  const value = Number(raw);
  return Number.isFinite(value) ? clamp01(value) : null;
}

export interface TheScannerProps {
  theme?: "dark" | "light";
  className?: string;
  /** hold the belt if you want to drive the run yourself */
  playing?: boolean;
  defaultPlaying?: boolean;
  onPlayingChange?: (playing: boolean) => void;
}

export function TheScanner({ theme = "dark", className, playing: controlled, defaultPlaying = true, onPlayingChange }: TheScannerProps) {
  const posed = React.useMemo(posedFromQuery, []);
  const posedRef = React.useRef(posed);
  posedRef.current = posed;

  const [own, setOwn] = React.useState(defaultPlaying);
  const playing = posed === null ? (controlled ?? own) : false;
  const setPlaying = React.useCallback(
    (next: boolean) => {
      if (controlled === undefined) setOwn(next);
      onPlayingChange?.(next);
    },
    [controlled, onPlayingChange],
  );

  const root = React.useRef<HTMLDivElement | null>(null);
  const inView = useInView(root);
  const readout = React.useRef<HTMLSpanElement | null>(null);
  const beam = React.useRef<SVGPathElement | null>(null);
  const built = React.useMemo(
    () => ({
      carried: Array.from({ length: CARRIERS }, () => React.createRef<SVGGElement>()),
      messy: Array.from({ length: CARRIERS }, () => React.createRef<SVGGElement>()),
      neat: Array.from({ length: CARRIERS }, () => React.createRef<SVGGElement>()),
    }),
    [],
  );
  const frame = React.useRef(0);
  const last = React.useRef(0);
  const grab = React.useRef(0);
  const playRef = React.useRef(playing);
  const [pressing, setPressing] = React.useState(false);

  const state = React.useRef({ clock: 0, phase: posed ?? STILL_PHASE, want: posed ?? STILL_PHASE });

  const paint = React.useCallback(() => {
    const s = state.current;
    const phase = s.phase;
    for (let index = 0; index < CARRIERS; index++) {
      const x = carrierX(phase, index);
      const carried = built.carried[index]?.current;
      const rumpledEl = built.messy[index]?.current;
      const neatEl = built.neat[index]?.current;
      carried?.setAttribute("transform", translateAlong(P, [x, 0, 0]));
      /* the two halves of a load sit in the same tray; the messy one is traded
         for the neat one at a point the near wall keeps out of sight */
      const rumpled = x < SWAP;
      if (rumpledEl) rumpledEl.style.opacity = rumpled ? "1" : "0";
      if (neatEl) neatEl.style.opacity = rumpled ? "0" : "1";
    }
    const glow = scanGlow(phase);
    if (beam.current) {
      beam.current.setAttribute("d", beamAt(beamZ(phase)));
      beam.current.style.opacity = (0.14 + 0.86 * glow).toFixed(3);
    }
    const text = stateText(phase);
    if (readout.current && readout.current.textContent !== text) readout.current.textContent = text;
    const host = root.current;
    if (host) {
      const now = String(Math.round(clamp01(s.want) * 100));
      if (host.getAttribute("aria-valuenow") !== now) {
        host.setAttribute("aria-valuenow", now);
        host.setAttribute("aria-valuetext", `${text} — ${now} per cent through the run`);
      }
    }
  }, [built]);

  const stop = React.useCallback(() => {
    cancelAnimationFrame(frame.current);
    frame.current = 0;
  }, []);

  const run = React.useCallback(() => {
    if (frame.current) return;
    last.current = 0;
    const step = (now: number) => {
      const dt = last.current ? Math.min((now - last.current) / 1000, MOST_DT) : 1 / 60;
      last.current = now;
      const calm = asksForStillness();
      const s = state.current;
      const still = posedRef.current;
      if (still !== null) {
        s.phase = still;
        s.want = still;
      } else if (playRef.current && !calm) {
        s.clock += dt;
        s.phase = phaseAt(s.clock);
        s.want = s.phase;
      } else {
        s.phase = calm ? s.want : follow(s.phase, s.want, dt, SEEK);
      }
      paint();
      const settled = Math.abs(s.phase - s.want) < 1e-3;
      frame.current = still !== null || (playRef.current && !calm) || (!calm && !settled) ? requestAnimationFrame(step) : 0;
    };
    frame.current = requestAnimationFrame(step);
  }, [paint]);

  React.useEffect(() => {
    if (inView) run();
    else stop();
  }, [inView, run, stop]);

  React.useEffect(() => {
    playRef.current = playing;
    if (posedRef.current !== null) return;
    const s = state.current;
    if (playing) {
      // pick the run up where the belt was left standing
      s.clock = s.phase * PERIOD;
    } else {
      // put it down where it stands, and let the reader take it from there
      s.want = s.phase;
    }
    if (playing || inView) run();
  }, [playing, inView, run]);

  React.useEffect(() => () => stop(), [stop]);
  React.useEffect(() => paint(), [paint]);

  /* reduced motion: hold the frame the drawing is about — a load leaving the
     mouth — and let the reader take it from there */
  const stillness = useStillness();
  React.useEffect(() => {
    if (!stillness || posedRef.current !== null) return;
    const s = state.current;
    s.phase = STILL_PHASE;
    s.want = STILL_PHASE;
    paint();
  }, [stillness, paint]);

  /** the pointer runs the length of the plate: nought at the left, one at the right */
  const valueAt = (clientX: number) => {
    const box = root.current?.getBoundingClientRect();
    if (!box || !box.width) return null;
    return clamp01((clientX - (box.left + box.width * 0.06)) / (box.width * 0.88));
  };

  const seekTo = React.useCallback(
    (phase: number) => {
      state.current.want = clamp01(phase);
      run();
    },
    [run],
  );

  return (
    <div className={className ? `iso the-scanner ${className}` : "iso the-scanner"} data-theme={theme}>
      <div className="the-scanner-plate">
        <div
          ref={root}
          className="the-scanner-stage"
          role="slider"
          tabIndex={playing ? -1 : 0}
          data-interactive={playing ? undefined : ""}
          aria-label="A benchtop inspection scanner in isometric view: parcels ride in on the belt from the left, pass under the light that sweeps the tunnel mouth, and come out squared away"
          aria-readonly={playing}
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={Math.round(STILL_PHASE * 100)}
          aria-valuetext="clear — 72 per cent through the run"
          style={{ touchAction: "pan-y" }}
          onPointerDown={(event) => {
            if (playing) return;
            const at = valueAt(event.clientX);
            if (at === null) return;
            event.currentTarget.setPointerCapture(event.pointerId);
            // hold the belt where it stands rather than throwing it at the pointer
            grab.current = state.current.want - at;
            setPressing(true);
            seekTo(at + grab.current);
          }}
          onPointerMove={(event) => {
            if (playing || !pressing) return;
            const at = valueAt(event.clientX);
            if (at === null) return;
            seekTo(at + grab.current);
          }}
          onPointerUp={(event) => {
            if (event.currentTarget.hasPointerCapture(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId);
            setPressing(false);
          }}
          onPointerCancel={() => setPressing(false)}
          onKeyDown={(event) => {
            if (playing) return;
            const step = event.shiftKey ? 0.16 : 0.05;
            let next: number | null = null;
            if (event.key === "ArrowLeft" || event.key === "ArrowDown") next = state.current.want - step;
            else if (event.key === "ArrowRight" || event.key === "ArrowUp") next = state.current.want + step;
            else if (event.key === "Home") next = 0;
            else if (event.key === "End") next = 1;
            if (next === null) return;
            event.preventDefault();
            seekTo(next);
          }}
        >
          <IsoFigure
            width={WIDTH}
            height={HEIGHT}
            className="the-scanner-figure"
            label="A benchtop inspection scanner in isometric view: parcels ride in on the belt from the left, pass under the light that sweeps the tunnel mouth, and come out squared away"
          >
            {BACK_PARTS.map((item, index) => (
              <Solid key={`back${index}`} paths={item.paths} tone={item.tone} crease={item.crease} lit={item.lit} halo={item.halo} className={item.mark} />
            ))}
            {BACK_LINES.map((item, index) => (
              <Line key={`backink${index}`} d={item.d} tone={item.tone} className={item.className} free={item.free} />
            ))}

            {/* the belt tread: the trim lines are fixed, and every slat is cut
                to land on both of them, so the tread reads as an endless surface */}
            {BELT_TRIM_LINES.map((item, index) => (
              <Line key={`tread${index}`} d={item.d} tone={item.tone} className={item.className} free={item.free} />
            ))}
            <Line d={BELT_SLATS} tone="faint" />

            {Array.from({ length: CARRIERS }, (_, index) => (
              <g key={`carrier${index}`} ref={built.carried[index]}>
                {TRAY_PARTS.map((item, at) => (
                  <Solid key={`tray${at}`} paths={item.paths} tone={item.tone} crease={item.crease} lit={item.lit} halo={item.halo} className={item.mark} />
                ))}
                {TRAY_LINES.map((item, at) => (
                  <Line key={`trayink${at}`} d={item.d} tone={item.tone} className={item.className} free={item.free} />
                ))}
                <g ref={built.messy[index]}>
                  {MESSY_PARTS.map((item, at) => (
                    <Solid key={`messy${at}`} paths={item.paths} tone={item.tone} crease={item.crease} lit={item.lit} halo={item.halo} className={item.mark} />
                  ))}
                  {MESSY_LINES.map((item, at) => (
                    <Line key={`messyink${at}`} d={item.d} tone={item.tone} className={item.className} free={item.free} />
                  ))}
                </g>
                <g ref={built.neat[index]}>
                  {NEAT_PARTS.map((item, at) => (
                    <Solid key={`neat${at}`} paths={item.paths} tone={item.tone} crease={item.crease} lit={item.lit} halo={item.halo} className={item.mark} />
                  ))}
                  {NEAT_LINES.map((item, at) => (
                    <Line key={`neatink${at}`} d={item.d} tone={item.tone} className={item.className} free={item.free} />
                  ))}
                </g>
              </g>
            ))}

            {IN_PARTS.map((item, index) => (
              <Solid key={`in${index}`} paths={item.paths} tone={item.tone} crease={item.crease} lit={item.lit} halo={item.halo} className={item.mark} />
            ))}
            {IN_LINES.map((item, index) => (
              <Line key={`inink${index}`} d={item.d} tone={item.tone} className={item.className} free={item.free} />
            ))}
            {VAULT_PARTS.map((item, index) => (
              <Solid key={`vault${index}`} paths={item.paths} tone={item.tone} crease={item.crease} lit={item.lit} halo={item.halo} className={item.mark} />
            ))}
            {VAULT_LINES.map((item, index) => (
              <Line key={`vaultink${index}`} d={item.d} tone={item.tone} className={item.className} free={item.free} />
            ))}
            {NEAR_PARTS.map((item, index) => (
              <Solid key={`near${index}`} paths={item.paths} tone={item.tone} crease={item.crease} lit={item.lit} halo={item.halo} className={item.mark} />
            ))}
            {NEAR_LINES.map((item, index) => (
              <Line key={`nearink${index}`} d={item.d} tone={item.tone} className={item.className} free={item.free} />
            ))}

            {/* the one lit thing in the drawing: the scan band, sweeping the mouth */}
            <path ref={beam} className="the-scanner-beam" d={beamAt(beamZ(STILL_PHASE))} style={{ opacity: 0.5 }} />

            {FRONT_PARTS.map((item, index) => (
              <Solid key={`front${index}`} paths={item.paths} tone={item.tone} crease={item.crease} lit={item.lit} halo={item.halo} className={item.mark} />
            ))}
            {FRONT_LINES.map((item, index) => (
              <Line key={`frontink${index}`} d={item.d} tone={item.tone} className={item.className} free={item.free} />
            ))}
          </IsoFigure>
        </div>

        <span ref={readout} className="the-scanner-readout" data-readout="">
          {stateText(STILL_PHASE)}
        </span>

        <button
          type="button"
          className="the-scanner-control"
          aria-label={playing ? "Pause the run and take the belt" : "Play the run"}
          title={playing ? "Pause" : "Play"}
          onClick={() => setPlaying(!playing)}
        >
          <span className="the-scanner-swap" aria-hidden="true">
            <HugeiconsIcon className="the-scanner-glyph" data-on={playing ? "" : undefined} icon={PauseIcon} size={16} strokeWidth={1.6} />
            <HugeiconsIcon className="the-scanner-glyph" data-on={playing ? undefined : ""} icon={PlayIcon} size={16} strokeWidth={1.6} />
          </span>
        </button>
      </div>
    </div>
  );
}

/* The Scanner — a benchtop inspection scanner over a conveyor line. A parcel
   rides in on the belt from the left, slides out of sight behind the tunnel's
   near wall, is scanned by the light that sweeps the mouth, and comes out the
   far side square and clean. Nothing is cut away: the tunnel is a solid arch
   over the belt, and its near wall hides the swap exactly the way a real
   machine hides what is inside it.
   Every number below is a world unit along x (the line), y (across it) and z
   (up). One clock drives the belt, both carriers and the scan light. */

import {
  corners,
  cylinder,
  extrude,
  fitProjection,
  insetPlan,
  iso,
  lineOnTop,
  pathOf,
  planOutline,
  ringOf,
  sideSeam,
  slabOf,
  type LineTone,
  type Plan,
  type Plane,
  type Point3,
  type Projection,
  type SolidPaths,
  type Tone,
} from "@/components/anatomy/iso-kit";
import { circleSection, frameAlong, prismOf, rectSection } from "@/components/anatomy/axis-parts";

export const WIDTH = 600;
const PAD = 22;

const clamp01 = (x: number) => (x < 0 ? 0 : x > 1 ? 1 : x);
const smooth01 = (x: number) => {
  const t = clamp01(x);
  return t * t * (3 - 2 * t);
};

/* ——— the bench ———
   Long enough that a parcel is seen riding in well before the tunnel swallows
   it, and no longer: the machine, not the bench, is the subject. */
export const BED: Plan = { x: -190, y: -74, w: 380, d: 148, r: 10 };
export const BED_Z0 = 60;
export const BED_Z1 = 70;

/* ——— the belt, and the two lines its tread hangs from ———
   The tread is a run of open slats that span the belt from trim to trim; each
   slat's ends land exactly on the trim line, and each trim line's ends land
   exactly on a corner of the belt's top face. Nothing floats. */
export const BELT: Plan = { x: -170, y: -44, w: 340, d: 88, r: 3 };
export const BELT_Z0 = 70;
export const BELT_H = 5;
export const BELT_Z1 = BELT_Z0 + BELT_H;
export const BELT_TRIM = 41;
export const SLAT_PITCH = 12;

/* ——— the rails either side of the belt, and their rule marks ——— */
export const RAIL_Y = 46;
export const RAIL_W = 14;

/* ——— the tunnel: a tall gantry, so its near wall can hide what it must ——— */
export const TUN_X0 = -60;
export const TUN_X1 = 60;
export const WALL_IN = 62;
export const WALL_OUT = 74;
export const WALL_Z0 = BED_Z1;
export const WALL_Z1 = 184;
const VAULT_HALF = WALL_OUT;
const VAULT_RISE = 30;
export const VAULT_APEX = WALL_Z1 + VAULT_RISE;

/* ——— the covered approach and the covered outfeed ———
   Two short portals of the same section as the tunnel, one either side of the
   gap the scan light reads across. */
export const IN_X0 = -152;
export const IN_X1 = -100;
export const HOOD_X0 = 100;
export const HOOD_X1 = 152;
export const CAN_TOP = 148;
const CAN_LID = CAN_TOP + 12;
export const MOUTH_X1 = TUN_X1 + 8;

/* ——— the carrier path, and where a load is traded for a clean one ———
   SWAP sits deep under the near wall's shadow: nothing in the drawing is at
   that screen spot but the wall itself, so the trade is never seen. */
export const X_START = -150;
export const X_END = 150;
export const SPAN = X_END - X_START;
export const BELT_SPEED = 26;
export const PERIOD = SPAN / BELT_SPEED;
export const CARRIERS = 2;
export const SWAP = -56;

/* ——— the scan light: the aperture, and the zone that lights it ——— */
export const SCAN_LO = 20;
export const SCAN_HI = 72;
export const BEAM_X = TUN_X1 - 2;
export const BEAM_HALF = 44;
export const BEAM_Z0 = 100;
export const BEAM_Z1 = 160;

/* ——— what a drawing is made of ——— */
export interface Part {
  paths: SolidPaths;
  tone: Tone;
  crease: Tone | "none";
  lit: boolean;
  halo?: boolean;
  mark?: string;
}
export interface Ink {
  d: string;
  tone: LineTone;
  className?: string;
  free?: boolean | "start" | "end";
}
const part = (paths: SolidPaths, tone: Tone = "mid", crease: Tone | "none" = "faint", lit = false, mark?: string, halo = false): Part => ({ paths, tone, crease, lit, mark, halo });
const ink = (d: string, tone: LineTone = "lo", extra: { className?: string; free?: boolean | "start" | "end" } = {}): Ink => ({ d, tone, ...extra });

/** a line drawn on a wall's outer face (constant y), for rules and marks */
const onFaceY = (y: number, points: Plane[]) => pathOf(points.map(([x, z]) => iso([x, y, z], P)), false);
/** a line drawn in a mouth plane (constant x) */
const onFaceX = (x: number, points: Plane[]) => pathOf(points.map(([y, z]) => iso([x, y, z], P)), false);

/** a rounded rectangle turned in plan, for a parcel knocked askew */
function rrect(cx: number, cy: number, w: number, d: number, r: number, angle: number, steps = 6): Plane[] {
  const c = Math.cos(angle);
  const s = Math.sin(angle);
  return ringOf({ x: -w / 2, y: -d / 2, w, d, r }, steps).map(([x, y]) => [cx + x * c - y * s, cy + x * s + y * c] as Plane);
}

/** an axis-aligned block between two corners, creased on the edges of its faces */
function blockAt(x0: number, x1: number, y0: number, y1: number, z0: number, z1: number): SolidPaths {
  const frame = frameAlong([(x0 + x1) / 2, y0, (z0 + z1) / 2], [(x0 + x1) / 2, y1, (z0 + z1) / 2]);
  return prismOf(frame, rectSection(x1 - x0, z1 - z0), 0, y1 - y0, P, { creases: true });
}

/** a round bar between two points: how every pipe and knob is drawn */
const pipe = (from: Point3, to: Point3, radius: number, steps = 12) =>
  prismOf(frameAlong(from, to), circleSection(radius, steps), 0, Math.hypot(to[0] - from[0], to[1] - from[1], to[2] - from[2]), P, { creases: false });

/** the circle the vault was struck from: the centre it rings about and its radius */
const VAULT_C = (() => {
  const radius = (VAULT_HALF * VAULT_HALF + VAULT_RISE * VAULT_RISE) / (2 * VAULT_RISE);
  return { r: radius, cz: WALL_Z1 - (radius - VAULT_RISE) };
})();

/** the vault's crown arc, as [y, z] pairs from one springline to the other */
function vaultArc(steps: number): Plane[] {
  const a0 = Math.asin(VAULT_HALF / VAULT_C.r);
  const out: Plane[] = [];
  for (let index = 0; index <= steps; index++) {
    const angle = a0 - (2 * a0 * index) / steps;
    out.push([VAULT_C.r * Math.sin(angle), VAULT_C.cz + VAULT_C.r * Math.cos(angle)]);
  }
  return out;
}

/** a band up the vault, from its foot toward the crown: the arch of every rib */
function archBand(inner: number, outer: number, steps = 16): Plane[] {
  const at = (radius: number, y: number): Plane => [y, VAULT_C.cz + Math.sqrt(Math.max(radius * radius - y * y, 0))];
  const out: Plane[] = [];
  for (let index = 0; index <= steps; index++) out.push(at(outer, -VAULT_HALF + (2 * VAULT_HALF * index) / steps));
  for (let index = steps; index >= 0; index--) out.push(at(inner, -VAULT_HALF + (2 * VAULT_HALF * index) / steps));
  return out;
}

/* ——— the extremes the camera has to hold ——— */
function extremes(): Point3[] {
  const out: Point3[] = [];
  for (const [x, y] of corners(BED, 0)) out.push([x, y, 0], [x, y, BED_Z1]);
  for (const [x, y] of corners(BELT, 0)) out.push([x, y, BELT_Z0], [x, y, BELT_Z1]);
  for (const y of [RAIL_Y + RAIL_W, -RAIL_Y - RAIL_W]) out.push([BELT.x - 6, y, BED_Z1 + 7], [BELT.x + BELT.w + 6, y, BED_Z1 + 7]);
  for (const x of [TUN_X0, TUN_X1, MOUTH_X1]) {
    out.push([x, -WALL_OUT, WALL_Z0], [x, WALL_OUT, WALL_Z0], [x, -WALL_OUT, WALL_Z1], [x, WALL_OUT, WALL_Z1]);
    for (const [y, z] of vaultArc(8)) out.push([x, y, z]);
  }
  for (const x of [IN_X0 - 3, IN_X1 + 3, HOOD_X0 - 3, HOOD_X1 + 3]) {
    out.push([x, -WALL_OUT, WALL_Z0], [x, WALL_OUT, WALL_Z0], [x, -WALL_OUT, CAN_LID], [x, WALL_OUT, CAN_LID]);
  }
  for (const x of [X_START, X_END]) out.push([x - 30, -22, BELT_Z1], [x + 30, 22, BELT_Z1 + 26], [x - 30, 22, BELT_Z1 + 26], [x + 30, -22, BELT_Z1 + 26]);
  out.push([BEAM_X, -BEAM_HALF, BEAM_Z0], [BEAM_X, BEAM_HALF, BEAM_Z1]);
  return out;
}

const UNIT: Projection = { origin: [0, 0], scale: 1 };
const RAW = extremes().map((point) => iso(point, UNIT));
const SPAN_X = Math.max(...RAW.map(([x]) => x)) - Math.min(...RAW.map(([x]) => x));
const SPAN_Y = Math.max(...RAW.map(([, y]) => y)) - Math.min(...RAW.map(([, y]) => y));
/** the plate is cut to the drawing's own shape, so nothing is padded away */
export const HEIGHT = Math.round((WIDTH - PAD * 2) * (SPAN_Y / SPAN_X) + PAD * 2);
export const P: Projection = fitProjection(extremes(), WIDTH, HEIGHT, { pad: PAD });

