  const out: string[] = [];
  for (let x = BELT.x + 8; x <= BELT.x + BELT.w - 7.99; x += SLAT_PITCH) out.push(lineOnTop([x, -BELT_TRIM], [x, BELT_TRIM], BELT_TREAD_Z, P));
  return out.join("");
})();

